// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceFullScanScriptInspector {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceFullScanScriptInspector = UniffiVTableCallbackInterfaceFullScanScriptInspector(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeFullScanScriptInspector.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface FullScanScriptInspector: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeFullScanScriptInspector.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface FullScanScriptInspector: handle missing in uniffiClone")
            }
        },
        inspect: { (
            uniffiHandle: UInt64,
            keychain: RustBuffer,
            index: UInt32,
            script: UInt64,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterTypeFullScanScriptInspector.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.inspect(
                     keychain: try FfiConverterTypeKeychainKind_lift(keychain),
                     index: try FfiConverterUInt32.lift(index),
                     script: try FfiConverterTypeScript_lift(script)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceFullScanScriptInspector> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceFullScanScriptInspector>.allocate(capacity: 1)
