// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfacePersistence {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfacePersistence = UniffiVTableCallbackInterfacePersistence(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypePersistence.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface Persistence: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypePersistence.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface Persistence: handle missing in uniffiClone")
            }
        },
        initialize: { (
            uniffiHandle: UInt64,
            uniffiOutReturn: UnsafeMutablePointer<UInt64>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> ChangeSet in
                guard let uniffiObj = try? FfiConverterTypePersistence.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try uniffiObj.initialize(
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterTypeChangeSet_lower($0) }
            uniffiTraitInterfaceCallWithError(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn,
                lowerError: FfiConverterTypePersistenceError_lower
            )
        },
        persist: { (
            uniffiHandle: UInt64,
            changeset: UInt64,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterTypePersistence.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try uniffiObj.persist(
                     changeset: try FfiConverterTypeChangeSet_lift(changeset)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCallWithError(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn,
                lowerError: FfiConverterTypePersistenceError_lower
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfacePersistence> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfacePersistence>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitPersistence() {
    uniffi_bdkffi_fn_init_callback_vtable_persistence(UniffiCallbackInterfacePersistence.vtablePtr)
}

